SELECT  *
FROM REP_REVEAL
WHERE
	1=1

		AND REP_ID = #{repId,jdbcType=VARCHAR}


		AND REPORT_NAME = #{reportName,jdbcType=VARCHAR}


		AND PRODID = #{prodId,jdbcType=VARCHAR}


		AND DATE_FORMAT(START_DATE,'%Y-%m-%d') = #{startDate,jdbcType=VARCHAR}


		AND  DATE_FORMAT(END_DATE,'%Y-%m-%d') = #{endDate,jdbcType=VARCHAR}

	AND STATUS = 'E'
	/** AND CONFIRM_STATUS = '01' **/
	limit 1

